<?php
declare(strict_types=1);

$profiles = array('default', 'compact', 'slate', 'wide');
$styles = '<style>[data-blocks-engine-capture-device-document]{display:none}.bar{display:block;width:20px;height:3px;background:currentColor}.menu-cue{width:32px;height:32px}.cue-frame,.cue-bars{display:block}</style>';
$body = '';
foreach ($profiles as $index => $profile) {
    $styles .= '<style data-blocks-engine-capture-document-scope="' . $profile . '" data-blocks-engine-capture-source-media="screen" media="not all">html[data-selected-profile="' . $profile . '"] [data-blocks-engine-capture-device-document="' . $profile . '"]{display:block;--profile-gap:' . (8 + $index * 4) . 'px}[data-blocks-engine-capture-device-document="' . $profile . '"] .copy{margin-top:var(--profile-gap)}</style>';
    $body .= '<div class="frame host-state profile-' . $profile . ' more-context" data-blocks-engine-capture-device-document="' . $profile . '" data-blocks-engine-capture-document-scope="' . $profile . '"><div class="generic-frame"><header><div id="toggle-' . $profile . '" class="menu-cue" role="button" tabindex="0" aria-label="Open navigation" data-blocks-engine-capture-dialog-trigger="panel-' . $profile . '" aria-controls="panel-' . $profile . '" aria-expanded="false"><div class="cue-frame"><div class="cue-bars"><span class="bar"></span><span class="bar"></span><span class="bar"></span></div></div></div><div hidden id="panel-' . $profile . '" data-blocks-engine-capture-dialog-panel="panel-' . $profile . '"><p>Navigation panel</p><button data-blocks-engine-capture-dialog-close="panel-' . $profile . '">Close</button></div></header><main><h1>Scoped document</h1><p class="copy">Editable document copy.</p></main><footer><p>Footer copy</p><iframe src="https://example.test/embed" title="Independent frame" width="100" height="50"></iframe></footer></div></div>';
}
$selector = <<<'JS'
(function(){var profiles=['default','compact','slate','wide'],match=location.search.match(/[?&]profile=([a-z]+)/),key=match?match[1]:'default';if(profiles.indexOf(key)<0)key='default';document.documentElement.setAttribute('data-selected-profile',key);document.querySelector('meta[name="viewport"]').content='width=device-width, initial-scale=1';document.querySelectorAll('[data-blocks-engine-capture-document-scope][data-blocks-engine-capture-source-media]').forEach(function(style){style.media=style.getAttribute('data-blocks-engine-capture-document-scope')===key?style.getAttribute('data-blocks-engine-capture-source-media'):'not all';});})();
JS;
$runtime = <<<'JS'
document.querySelectorAll('[data-blocks-engine-capture-dialog-trigger]').forEach(function(trigger){function open(){var panel=document.getElementById(trigger.getAttribute('aria-controls'));panel.hidden=false;trigger.setAttribute('aria-expanded','true');panel.querySelector('button').focus();}trigger.addEventListener('click',open);trigger.addEventListener('keydown',function(event){if(event.key==='Enter'||event.key===' '){event.preventDefault();open();}});});function close(panel){panel.hidden=true;var trigger=document.querySelector('[aria-controls="'+panel.id+'"]');trigger.setAttribute('aria-expanded','false');trigger.focus();}document.querySelectorAll('[data-blocks-engine-capture-dialog-close]').forEach(function(button){button.addEventListener('click',function(){close(document.getElementById(button.getAttribute('data-blocks-engine-capture-dialog-close')));});});document.addEventListener('keydown',function(event){if(event.key==='Escape')document.querySelectorAll('[data-blocks-engine-capture-dialog-panel]').forEach(function(panel){if(!panel.hidden)close(panel);});});
JS;
return array('entrypoint' => 'index.html', 'files' => array('index.html' => '<!doctype html><html><head><meta name="viewport">' . $styles . '<script>' . $selector . '</script></head><body>' . $body . '<script>' . $runtime . '</script></body></html>'));
